# ---------------------------------------------------------------------------
#  MQL5 EA audit runner (generated by mql5-ea-auditor-optimizer-and-refiner)
#  Runs on the user's Windows PC: compile -> tester runs listed below -> collect reports.
#  Close MetaTrader 5 before running (the tester needs the data folder to itself).
#  Usage:  powershell -ExecutionPolicy Bypass -File run_<stage>.ps1 [-Terminal "<path>\terminal64.exe"] [-Portable]
# ---------------------------------------------------------------------------
param(
   [string]$Terminal = "",
   [switch]$Portable,
   [int]$TimeoutMinutes = 240
)
$ErrorActionPreference = "Stop"
$Audit   = $PSScriptRoot
$EaDir   = Split-Path $Audit -Parent
$EaFile  = '__EA_FILE__'
$Folder  = '__EA_FOLDER__'
$Compile = __COMPILE__
$Runs    = @()
__RUNS__

function Say($m) { Write-Host "[audit] $m" }

#--- 1) locate terminal64.exe / metaeditor64.exe
if (-not $Terminal) {
   $cands = @()
   foreach ($root in @($env:ProgramFiles, ${env:ProgramFiles(x86)})) {
      if ($root) { $cands += Get-ChildItem -Path $root -Filter terminal64.exe -Recurse -Depth 2 -ErrorAction SilentlyContinue }
   }
   if ($cands.Count -eq 0) { throw "terminal64.exe not found. Re-run with -Terminal '<path>\terminal64.exe'" }
   $Terminal = $cands[0].FullName
   if ($cands.Count -gt 1) { Say "Several MT5 installs found, using: $Terminal  (use -Terminal to choose)" }
}
$Install    = Split-Path $Terminal -Parent
$MetaEditor = Join-Path $Install "metaeditor64.exe"
if (-not (Test-Path $MetaEditor)) { throw "metaeditor64.exe not found next to $Terminal" }

#--- 2) data folder (portable = install folder, else the folder whose origin.txt points to the install)
$Data = $null
if ($Portable) { $Data = $Install }
else {
   $base = Join-Path $env:APPDATA "MetaQuotes\Terminal"
   foreach ($d in Get-ChildItem $base -Directory -ErrorAction SilentlyContinue) {
      $o = Join-Path $d.FullName "origin.txt"
      if (Test-Path $o) {
         $txt = (Get-Content $o -Encoding Unicode -Raw).Trim().TrimEnd('\')
         if ($txt -ieq $Install.TrimEnd('\')) { $Data = $d.FullName; break }
      }
   }
}
if (-not $Data) { throw "Terminal data folder not found. In MT5: File > Open Data Folder; or use -Portable." }
Say "Terminal: $Terminal"
Say "Data:     $Data"

#--- 3) MT5 must be closed
$running = Get-Process terminal64 -ErrorAction SilentlyContinue | Where-Object { $_.Path -eq $Terminal }
if ($running) { throw "This MT5 terminal is running. Close it and run again." }

#--- 4) copy the EA (with its includes) and the .set files
$Dst = Join-Path $Data "MQL5\Experts\$Folder"
if (Test-Path $Dst) { Remove-Item $Dst -Recurse -Force }
New-Item -ItemType Directory -Path $Dst | Out-Null
Get-ChildItem $EaDir -Force | Where-Object { $_.Name -ne "_audit" -and $_.Name -ne ".git" } |
   ForEach-Object { Copy-Item $_.FullName -Destination $Dst -Recurse -Force }
$Profiles = Join-Path $Data "MQL5\Profiles\Tester"
New-Item -ItemType Directory -Path $Profiles -Force | Out-Null
Get-ChildItem $Audit -Filter *.set | ForEach-Object { Copy-Item $_.FullName $Profiles -Force }
$Results = Join-Path $Audit "results"
New-Item -ItemType Directory -Path $Results -Force | Out-Null

#--- 5) compile
if ($Compile) {
   $log = Join-Path $Audit "compile.log"
   if (Test-Path $log) { Remove-Item $log }
   $src = Join-Path $Dst $EaFile
   Say "Compiling $src"
   $p = Start-Process -FilePath $MetaEditor -ArgumentList "/compile:`"$src`"", "/log:`"$log`"", "/include:`"$Data\MQL5`"" -PassThru -Wait
   if (-not (Test-Path $log)) { throw "No compile log written." }
   $logText = Get-Content $log -Encoding Unicode -Raw
   ($logText -split "\r?\n") | Where-Object { $_ -match "error|warning|Result" } | ForEach-Object { Write-Host $_ }
   $m = [regex]::Match($logText, "(\d+)\s+errors?,\s*(\d+)\s+warnings?")
   $ex5 = [IO.Path]::ChangeExtension($src, ".ex5")
   if (-not $m.Success) { throw "Compile result line not found in $log" }
   if ([int]$m.Groups[1].Value -gt 0 -or -not (Test-Path $ex5)) { throw "Compile FAILED ($($m.Groups[1].Value) errors). Send back _audit\compile.log." }
   Copy-Item $ex5 $Results -Force
   Say "Compiled: $($m.Groups[1].Value) errors, $($m.Groups[2].Value) warnings (from compile.log)"
}

#--- 6) tester runs
foreach ($r in $Runs) {
   $ini = Join-Path $Audit $r[0]
   $report = Join-Path $Data ($r[1] + $r[2])
   $start = Get-Date
   Say "Tester: $($r[0])"
   $targs = @("/config:`"$ini`"")
   if ($Portable) { $targs += "/portable" }
   $p = Start-Process -FilePath $Terminal -ArgumentList $targs -PassThru
   if (-not $p.WaitForExit($TimeoutMinutes * 60 * 1000)) { Say "Timeout - stopping terminal"; $p | Stop-Process -Force }
   Start-Sleep -Seconds 3
   if ((Test-Path $report) -and ((Get-Item $report).LastWriteTime -ge $start.AddSeconds(-5))) {
      Copy-Item $report $Results -Force
      $fwd = $report -replace '\.xml$', '.forward.xml'
      if ($r[2] -eq ".xml" -and (Test-Path $fwd)) { Copy-Item $fwd $Results -Force }
      Say "  report: $report"
   } else {
      Say "  NO fresh report for $($r[0]). Check $Data\Tester\logs and $Data\logs."
   }
}

#--- 7) tester journal (errors such as 'not enough money', 'invalid stops', '4756')
$tlog = Get-ChildItem (Join-Path $Data "Tester\logs") -Filter *.log -ErrorAction SilentlyContinue | Sort-Object LastWriteTime | Select-Object -Last 1
if ($tlog) { Copy-Item $tlog.FullName (Join-Path $Results "tester_journal.log") -Force }

#--- 8) optional local parsing (needs Python); otherwise send the folder back as-is
$py = Get-Command python -ErrorAction SilentlyContinue
if ($py) {
   Get-ChildItem $Results -Include *.htm, *.xml -Recurse | ForEach-Object {
      & python (Join-Path $Audit "scripts\parse_report.py") $_.FullName --json ($_.FullName + ".json")
   }
}
Say "Done. Send back the whole _audit folder (results\, compile.log)."
